    def __init__(self):
        self.d = {}
    def add(self, o):
        self.d[o.id] = o
    def get(self, i):
        return self.d[i]

class Order:
    def __init__(self, i):
        self.id = i
        self.status = "draft"
    def place(self):
        self.status = "placed"

